import type { MemberAddresses } from '@api/api-types.ts';

export const getSelectedAddressIndex = (
  addresses: MemberAddresses[],
  selectedAddress?: MemberAddresses | null,
): number => {
  if (addresses.length === 0) {
    return 0;
  }

  const selectedId = selectedAddress?.id;
  if (!selectedId) {
    return 0;
  }

  const matchedIndex = addresses.findIndex(
    (address: MemberAddresses): boolean => address.id === selectedId,
  );

  return matchedIndex >= 0 ? matchedIndex : 0;
};

export const resolveDeliveryAddress = (
  addresses: MemberAddresses[],
  selectedAddress?: MemberAddresses | null,
): MemberAddresses | null => {
  if (selectedAddress?.id) {
    const matchedAddress = addresses.find(
      (address: MemberAddresses): boolean => address.id === selectedAddress.id,
    );

    if (matchedAddress) {
      return matchedAddress;
    }

    if (selectedAddress.fields?.length) {
      return selectedAddress;
    }
  }

  return addresses[0] ?? selectedAddress ?? null;
};

import type { MemberAddresses } from '../src/api/api-types';
import {
  getSelectedAddressIndex,
  resolveDeliveryAddress,
} from '../src/utils/selected-address';

const hongKongAddress = {
  id: 'address-hk',
  key: 'hk',
  fields: [{ key: 'contactPerson', value: '哦哦哦' }],
  coordinate: { latitude: 0, longitude: 0 },
} as MemberAddresses;

const israelAddress = {
  id: 'address-il',
  key: 'il',
  fields: [{ key: 'contactPerson', value: 'zxy' }],
  coordinate: { latitude: 0, longitude: 0 },
} as MemberAddresses;

describe('selected address helpers', () => {
  test('resolves the saved selected address instead of the first list item', () => {
    const addresses = [hongKongAddress, israelAddress];

    expect(getSelectedAddressIndex(addresses, israelAddress)).toBe(1);
    expect(resolveDeliveryAddress(addresses, israelAddress)).toEqual(
      israelAddress,
    );
  });

  test('falls back to the first address when nothing is selected', () => {
    const addresses = [hongKongAddress, israelAddress];

    expect(getSelectedAddressIndex(addresses, null)).toBe(0);
    expect(resolveDeliveryAddress(addresses, null)).toEqual(hongKongAddress);
  });

  test('keeps the cached selected address when the list has not loaded yet', () => {
    expect(getSelectedAddressIndex([], israelAddress)).toBe(0);
    expect(resolveDeliveryAddress([], israelAddress)).toEqual(israelAddress);
  });

  test('falls back to the first remaining address when the selected id is gone', () => {
    expect(
      getSelectedAddressIndex([hongKongAddress], israelAddress),
    ).toBe(0);
    expect(
      resolveDeliveryAddress([hongKongAddress], israelAddress),
    ).toEqual(hongKongAddress);
  });
});

